-- Konsens V3 pedagogical journey core.
create table if not exists public.daily_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,session_date date not null default current_date,understand_completed_at timestamptz,predict_completed_at timestamptz,decide_completed_at timestamptz,learn_completed_at timestamptz,completed_at timestamptz,xp_earned integer not null default 0,score_delta numeric(8,2) not null default 0,created_at timestamptz not null default now(),unique(user_id,session_date));
alter table public.daily_sessions enable row level security;drop policy if exists daily_sessions_own on public.daily_sessions;create policy daily_sessions_own on public.daily_sessions for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);grant select,insert,update on public.daily_sessions to authenticated;
create table if not exists public.konsens_scores(user_id uuid primary key references public.profiles(id) on delete cascade,total_score numeric(6,2) not null default 50 check(total_score between 0 and 100),prediction_score numeric(6,2) not null default 50 check(prediction_score between 0 and 100),risk_score numeric(6,2) not null default 50 check(risk_score between 0 and 100),knowledge_score numeric(6,2) not null default 50 check(knowledge_score between 0 and 100),discipline_score numeric(6,2) not null default 50 check(discipline_score between 0 and 100),diversification_score numeric(6,2) not null default 50 check(diversification_score between 0 and 100),calibration_score numeric(6,2) not null default 50 check(calibration_score between 0 and 100),archetype text not null default 'Explorateur',streak_days integer not null default 0,best_streak integer not null default 0,updated_at timestamptz not null default now());
alter table public.konsens_scores enable row level security;drop policy if exists konsens_scores_read_own on public.konsens_scores;create policy konsens_scores_read_own on public.konsens_scores for select to authenticated using(auth.uid()=user_id);grant select on public.konsens_scores to authenticated;insert into public.konsens_scores(user_id) select id from public.profiles on conflict(user_id) do nothing;
create table if not exists public.replay_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,scenario_id uuid not null references public.replay_scenarios(id) on delete cascade,selected_choice integer not null,confidence smallint check(confidence between 0 and 100),score numeric(8,2),completed_at timestamptz not null default now());alter table public.replay_sessions enable row level security;drop policy if exists replay_sessions_own on public.replay_sessions;create policy replay_sessions_own on public.replay_sessions for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);grant select,insert on public.replay_sessions to authenticated;
create table if not exists public.scenario_simulations(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,title text not null,scenario_type text not null check(scenario_type in('dca','allocation','follow','cash','custom')),parameters jsonb not null default '{}'::jsonb,result_summary jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());alter table public.scenario_simulations enable row level security;drop policy if exists scenario_simulations_own on public.scenario_simulations;create policy scenario_simulations_own on public.scenario_simulations for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);grant select,insert,delete on public.scenario_simulations to authenticated;
create table if not exists public.consensus_snapshots(id uuid primary key default gen_random_uuid(),subject_type text not null check(subject_type in('market','asset')),subject_id uuid not null,community_probability numeric(6,4),ai_probability numeric(6,4),market_probability numeric(6,4),observed_at timestamptz not null default now(),unique(subject_type,subject_id,observed_at));alter table public.consensus_snapshots enable row level security;drop policy if exists consensus_snapshots_read on public.consensus_snapshots;create policy consensus_snapshots_read on public.consensus_snapshots for select to authenticated using(true);grant select on public.consensus_snapshots to authenticated;
alter table public.decision_journal add column if not exists expectation text;alter table public.decision_journal add column if not exists emotion text;alter table public.decision_journal add column if not exists reviewed_outcome text;
create or replace function public.ensure_daily_session() returns public.daily_sessions language plpgsql security definer set search_path=public as $$declare r public.daily_sessions;begin insert into public.daily_sessions(user_id,session_date) values(auth.uid(),current_date) on conflict(user_id,session_date) do nothing;select * into r from public.daily_sessions where user_id=auth.uid() and session_date=current_date;return r;end$$;grant execute on function public.ensure_daily_session() to authenticated;
create or replace function public.complete_daily_step(p_step text,p_xp integer default 10) returns public.daily_sessions language plpgsql security definer set search_path=public as $$declare r public.daily_sessions;begin perform public.ensure_daily_session();if p_step='understand' then update public.daily_sessions set understand_completed_at=coalesce(understand_completed_at,now()),xp_earned=xp_earned+case when understand_completed_at is null then p_xp else 0 end where user_id=auth.uid() and session_date=current_date;elsif p_step='predict' then update public.daily_sessions set predict_completed_at=coalesce(predict_completed_at,now()),xp_earned=xp_earned+case when predict_completed_at is null then p_xp else 0 end where user_id=auth.uid() and session_date=current_date;elsif p_step='decide' then update public.daily_sessions set decide_completed_at=coalesce(decide_completed_at,now()),xp_earned=xp_earned+case when decide_completed_at is null then p_xp else 0 end where user_id=auth.uid() and session_date=current_date;elsif p_step='learn' then update public.daily_sessions set learn_completed_at=coalesce(learn_completed_at,now()),xp_earned=xp_earned+case when learn_completed_at is null then p_xp else 0 end where user_id=auth.uid() and session_date=current_date;else raise exception 'invalid_step';end if;update public.daily_sessions set completed_at=coalesce(completed_at,case when understand_completed_at is not null and predict_completed_at is not null and decide_completed_at is not null and learn_completed_at is not null then now() end) where user_id=auth.uid() and session_date=current_date;select * into r from public.daily_sessions where user_id=auth.uid() and session_date=current_date;return r;end$$;grant execute on function public.complete_daily_step(text,integer) to authenticated;
create or replace function public.get_my_konsens_score() returns table(total_score numeric,prediction_score numeric,risk_score numeric,knowledge_score numeric,discipline_score numeric,diversification_score numeric,calibration_score numeric,archetype text,streak_days integer,best_streak integer) language plpgsql security definer set search_path=public as $$declare uid uuid:=auth.uid();knowledge numeric:=50;discipline numeric:=50;prediction numeric:=50;risk numeric:=50;diversification numeric:=50;calibration numeric:=50;total numeric:=50;arch text:='Explorateur';streak integer:=0;best integer:=0;begin select coalesce(avg(score),50) into knowledge from public.learning_progress where user_id=uid and completed_at is not null;select least(100,50+count(*)*2) into discipline from public.daily_sessions where user_id=uid and completed_at is not null and session_date>=current_date-30;select coalesce(least(100,50+avg(greatest(-25,least(25,coalesce(result_delta,0))))),50) into prediction from public.decision_journal where user_id=uid and decision_type='bet' and reviewed_at is not null;select greatest(0,least(100,75-coalesce(avg(case when credits>200 then 25 when credits>100 then 12 else 0 end),0))) into risk from public.decision_journal where user_id=uid;select case when count(distinct asset_id)>=5 then 85 when count(distinct asset_id)>=3 then 70 when count(distinct asset_id)>=2 then 60 else 50 end into diversification from public.positions where user_id=uid and asset_id is not null;select coalesce(greatest(0,least(100,100-avg(abs(confidence-coalesce(case when result_label in('correct','win','positive') then 100 else 0 end,50))))),50) into calibration from public.decision_journal where user_id=uid and confidence is not null and reviewed_at is not null;total:=round((knowledge*.20+discipline*.18+prediction*.20+risk*.16+diversification*.12+calibration*.14)::numeric,2);arch:=case when knowledge>=75 and risk>=70 then 'Analyste discipliné' when prediction>=75 then 'Prévisionniste' when diversification>=75 then 'Architecte de portefeuille' when discipline>=75 then 'Régulier' else 'Explorateur' end;select count(*)::int into streak from public.daily_sessions where user_id=uid and completed_at is not null and session_date>=current_date-6;select greatest(coalesce(k.best_streak,0),streak) into best from public.konsens_scores k where k.user_id=uid;insert into public.konsens_scores(user_id,total_score,prediction_score,risk_score,knowledge_score,discipline_score,diversification_score,calibration_score,archetype,streak_days,best_streak,updated_at) values(uid,total,prediction,risk,knowledge,discipline,diversification,calibration,arch,streak,best,now()) on conflict(user_id) do update set total_score=excluded.total_score,prediction_score=excluded.prediction_score,risk_score=excluded.risk_score,knowledge_score=excluded.knowledge_score,discipline_score=excluded.discipline_score,diversification_score=excluded.diversification_score,calibration_score=excluded.calibration_score,archetype=excluded.archetype,streak_days=excluded.streak_days,best_streak=excluded.best_streak,updated_at=now();return query select total,prediction,risk,knowledge,discipline,diversification,calibration,arch,streak,best;end$$;grant execute on function public.get_my_konsens_score() to authenticated;
insert into public.replay_scenarios(slug,title,era,setup,known_at_time,choices,reveal_text,lesson,source_urls,difficulty,active,position) values('covid-march-2020','Mars 2020 : panique sur les marchés','Mars 2020','Les marchés mondiaux chutent brutalement. Tu ignores encore la durée des confinements et l’ampleur des réponses monétaires.','["Volatilité extrême","Visibilité économique très faible","Banques centrales prêtes à intervenir"]'::jsonb,'[{"label":"Tout vendre","impact":"Tu réduis immédiatement le risque mais cristallises la baisse."},{"label":"Conserver","impact":"Tu acceptes la volatilité en gardant ton allocation."},{"label":"Renforcer progressivement","impact":"Tu répartis tes achats dans le temps sans tenter de deviner le point bas."}]'::jsonb,'Les marchés ont connu une chute rapide puis un puissant rebond, avec de fortes différences selon les secteurs.','Dans une crise, le bon réflexe n’est pas de connaître le futur mais de dimensionner son risque, son horizon et sa capacité à rester investi.',array['https://www.federalreserve.gov/monetarypolicy.htm'],'intermediate',true,1),('rates-2022','2022 : inflation et remontée des taux','2022','L’inflation accélère et les banques centrales commencent à relever fortement leurs taux.','["Inflation élevée","Taux en hausse","Valorisations technologiques élevées"]'::jsonb,'[{"label":"Concentrer sur la tech","impact":"Tu augmentes ton exposition aux actifs sensibles aux taux."},{"label":"Diversifier davantage","impact":"Tu répartis le risque entre plusieurs moteurs de performance."},{"label":"Rester 100% cash","impact":"Tu réduis la volatilité mais subis l’érosion de l’inflation."}]'::jsonb,'Les actions de croissance et les obligations ont souffert simultanément pendant une partie de 2022.','Taux, duration et valorisation sont reliés : apprendre ces relations aide à comprendre pourquoi plusieurs actifs peuvent baisser ensemble.',array['https://www.ecb.europa.eu/mopo/html/index.en.html'],'intermediate',true,2) on conflict(slug) do nothing;
